import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    admin_hash = hashlib.sha256(b'admin_secret_2024').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, api_key) VALUES ('admin', ?, 'admin', 'ak_prod_7f3a9b2c')", (admin_hash,))
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Allowlist of searchable fields
    allowed_fields = ['username', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above, value is user-controlled
    query = f"SELECT id, username, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/lookup', methods=['POST'])
def lookup_user():
    """Lookup user by exact username match."""
    data = request.get_json(force=True)
    username = data.get('username', '')

    db = get_db()
    # Parameterized query - safe
    result = db.execute("SELECT id, username, role FROM users WHERE username = ?", (username,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/audit', methods=['GET'])
def get_audit_log():
    """Retrieve audit log entries. Requires admin API key."""
    api_key = request.headers.get('X-API-Key', '')

    db = get_db()
    admin = db.execute("SELECT api_key FROM users WHERE role = 'admin'").fetchone()

    if not admin or api_key != admin['api_key']:
        return jsonify({'error': 'Unauthorized'}), 401

    limit = request.args.get('limit', '50')
    # Potential integer overflow but sqlite handles gracefully
    query = f"SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT {limit}"
    results = db.execute(query).fetchall()
    return jsonify([dict(r) for r in results])

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    init_db()
    debug_mode = os.environ.get('FLASK_DEBUG', '0') == '1'
    app.run(host='0.0.0.0', port=5000, debug=debug_mode)
